(()=>{const T=[...(window.NQ_EXTRA_TRANSLATIONS||[]),
['Lewati ke konten','Skip to content','跳转到内容'],['NeuroQuest, kembali ke Markas','NeuroQuest, back to Base','NeuroQuest，返回基地'],['Navigasi utama','Main navigation','主导航'],['Markas','Base','基地'],['Peta Misi','Mission Map','任务地图'],['Jurnal Riset','Research Journal','研究日志'],['Lihat progres pemain','View player progress','查看玩家进度'],['Aktifkan efek suara','Enable sound effects','开启音效'],['Matikan efek suara','Disable sound effects','关闭音效'],['Ekspedisi MRI Otak','Brain MRI Expedition','脑部 MRI 探险'],['Simulator skripsi','Thesis simulator','论文模拟器'],['Masuki lab Natasya dan selidiki apakah satu modul CBAM membantu AI membedakan empat kelas MRI otak.','Enter Natasya’s lab and investigate whether one CBAM module helps AI distinguish four brain MRI classes.','进入 Natasya 的实验室，研究一个 CBAM 模块是否能帮助 AI 区分四类脑部 MRI。'],['Mulai bermain','Start playing','开始游戏'],['Lanjutkan','Continue','继续'],['Main lagi','Play again','再次游玩'],['Tentang riset','About the research','关于研究'],['Lima stasiun lab, dari audit data sampai membaca prediksi.','Five lab stations, from auditing data to reading predictions.','五个实验站，从数据审核到读取预测结果。'],['Coba simulasi bebas','Try the free simulation','尝试自由模拟'],['Di balik eksperimen','Behind the experiment','实验背后的原理'],['Ubah satu prediksi pada matriks latihan dan lihat bagaimana skor tiap kelas ikut berubah.','Change one prediction in the practice matrix and see how each class score changes.','修改练习矩阵中的一个预测，观察每个类别的分数如何变化。'],['Cara bermain','How to play','玩法说明'],['Peta misi','Mission map','任务地图'],['Misi','Mission','任务'],['Audit Dataset','Audit Dataset','审核数据集'],['Temukan salinan MRI dan bagi data dengan adil.','Find duplicate MRI images and split the data fairly.','找出重复的 MRI 图像，并公平地划分数据。'],['Rakit CBAM','Assemble CBAM','组装 CBAM'],['Pasang modul perhatian ke EfficientNet-B0.','Add the attention module to EfficientNet-B0.','将注意力模块加入 EfficientNet-B0。'],['Latih Model','Train the Model','训练模型'],['Pasangkan seed dan pilih checkpoint lewat validasi.','Pair the seeds and choose the checkpoint through validation.','配对随机种子，并通过验证集选择检查点。'],['Uji Prediksi','Test Predictions','测试预测结果'],['Baca kesalahan per kelas dan bandingkan dua dataset.','Read class-level errors and compare two datasets.','分析各类别错误，并比较两个数据集。'],['Baca Grad-CAM','Read Grad-CAM','读取 Grad-CAM'],['Selidiki bagian gambar yang disorot model.','Investigate the image regions highlighted by the model.','研究模型突出显示的图像区域。'],['Laboratorium Eksperimen','Experiment Laboratory','实验室'],['Kamu yang mengoperasikan pipeline riset. Siapkan data, pasang CBAM, lalu jalankan satu eksperimen.','You operate the research pipeline. Prepare the data, install CBAM, then run one experiment.','你将操作整个研究流程。准备数据，安装 CBAM，然后运行一次实验。'],['PRAKTIK LANGSUNG','HANDS-ON PRACTICE','动手实践'],['Stasiun','Station','实验站'],['Audit data','Audit data','审核数据'],['Rakit model','Assemble model','组装模型'],['Jalankan eksperimen','Run experiment','运行实验'],['STASIUN 01 · AUDIT DATA','STATION 01 · DATA AUDIT','实验站 01 · 数据审核'],['Seret citra ke partisi dataset','Drag images into the dataset partitions','将图像拖入数据集分区'],['Tarik setiap citra ke data latih, validasi, atau uji. Contoh target: 4 latih, 1 validasi, 1 uji.','Drag each image to training, validation, or test. Example target: 4 training, 1 validation, 1 test.','将每张图像拖到训练、验证或测试区。示例目标：4 张训练、1 张验证、1 张测试。'],['Data latih','Training data','训练数据'],['Validasi','Validation','验证数据'],['Data uji','Test data','测试数据'],['Taruh citra di sini','Drop images here','将图像放在这里'],['Lanjut ke perakitan','Continue to assembly','继续组装'],['citra dipindahkan','images moved','张图像已移动'],['STASIUN 02 · ARSITEKTUR','STATION 02 · ARCHITECTURE','实验站 02 · 模型架构'],['Hubungkan jalur fitur CBAM','Connect the CBAM feature path','连接 CBAM 特征路径'],['Tekan modul dalam urutan operasi. Perhatikan bagaimana fitur melewati channel attention, spatial attention, pooling, lalu classifier.','Click the modules in operating order. Watch features pass through channel attention, spatial attention, pooling, then the classifier.','按运行顺序点击模块，观察特征依次经过通道注意力、空间注意力、池化和分类器。'],['Jalankan jalur fitur','Run the feature path','运行特征路径'],['Lanjut ke eksperimen','Continue to the experiment','继续实验'],['Klik modul perhatian untuk melihat aliran data.','Click the attention modules to see the data flow.','点击注意力模块查看数据流。'],['STASIUN 03 · EKSPERIMEN','STATION 03 · EXPERIMENT','实验站 03 · 实验'],['Jalankan model dan baca hasilnya','Run the model and read the results','运行模型并读取结果'],['Semua pengaturan sudah disamakan. Tekan tombol untuk menjalankan simulasi pasangan B0 dan B0 + CBAM.','All settings are matched. Press the button to run the B0 and B0 + CBAM comparison simulation.','所有设置保持一致。点击按钮运行 B0 与 B0 + CBAM 的对比模拟。'],['Jalankan 7 seed','Run 7 seeds','运行 7 个随机种子'],['B0 standar','Standard B0','标准 B0'],['B0 + CBAM','B0 + CBAM','B0 + CBAM'],['Perubahan macro-F1','Macro-F1 change','Macro-F1 变化'],['Simulasi pembelajaran. Hasil skripsi berasal dari model PyTorch yang kamu latih pada dataset yang sudah diaudit.','Learning simulation. Thesis results will come from the PyTorch model you train on the audited dataset.','这是学习模拟。论文结果将来自你在审核后数据集上训练的 PyTorch 模型。'],['Jurnal Riset','Research Journal','研究日志'],['Proposal Natasya Suryanto','Natasya Suryanto’s proposal','Natasya Suryanto 的研究计划'],['Rencana eksperimen klasifikasi empat kelas MRI otak dengan EfficientNet-B0 dan CBAM.','Experimental plan for four-class brain MRI classification with EfficientNet-B0 and CBAM.','使用 EfficientNet-B0 与 CBAM 进行四类脑部 MRI 分类的实验计划。'],['Ringkasan','Overview','概述'],['Metode','Method','方法'],['Evaluasi','Evaluation','评估'],['Jadwal & luaran','Schedule & outputs','时间表与成果'],['Glosarium','Glossary','术语表'],['Apa yang ingin Natasya ketahui?','What does Natasya want to know?','Natasya 想研究什么？'],['Tiga pertanyaan penelitian','Three research questions','三个研究问题'],['Empat label MRI','Four MRI labels','四种 MRI 标签'],['Mengapa per kelas?','Why report each class?','为什么分别报告每一类？'],['Sepuluh konfigurasi','Ten configurations','十种配置'],['Bagaimana hasilnya akan dibaca?','How will the results be read?','如何解读结果？'],['Panel Grad-CAM','Grad-CAM panels','Grad-CAM 图像面板'],['Jadwal kerja di proposal','Schedule in the proposal','研究计划时间表'],['Luaran skripsi','Thesis outputs','论文成果'],['Glosarium lab','Lab glossary','实验室术语表'],['Cari istilah atau artinya','Search for a term or meaning','搜索术语或含义'],['Misalnya, macro-F1','For example, macro-F1','例如 macro-F1'],['Buka jurnal','Open the journal','打开研究日志'],['Baca metode riset','Read the research method','阅读研究方法'],['Baca rencana evaluasi','Read the evaluation plan','阅读评估计划'],['Coba meja uji macro-F1','Try the Macro-F1 test bench','尝试 Macro-F1 测试台'],['Meja Uji Macro-F1','Macro-F1 Test Bench','Macro-F1 测试台'],['Eksperimen bebas','Free experiment','自由实验'],['Meja eksperimen','Experiment bench','实验台'],['Ubah satu prediksi pada 100 citra buatan dan lihat dampaknya pada perbandingan dua model.','Change one prediction in 100 synthetic images and see its effect on the model comparison.','修改 100 张合成图像中的一个预测，观察它对模型比较的影响。'],['Matriks model skenario','Scenario model matrix','模拟模型矩阵'],['Pindahkan satu prediksi','Move one prediction','移动一个预测'],['Pilih sel yang berisi citra. Lalu pilih kelas prediksi baru untuk satu citra di sel itu. Label datasetnya tetap.','Choose a cell containing images, then choose a new predicted class for one image in that cell. The dataset label stays the same.','选择一个包含图像的单元格，再为其中一张图像选择新的预测类别。数据集标签保持不变。'],['F1 setiap kelas','F1 for each class','每一类的 F1'],['Kedua model memulai dari matriks yang sama.','Both models start from the same matrix.','两个模型从同一个矩阵开始。'],['Pindahkan 1 citra','Move 1 image','移动 1 张图像'],['Urungkan','Undo','撤销'],['Prediksi baru','New prediction','新预测'],['Ruang MRI','MRI Room','MRI 房间'],['Atur ulang ekspedisi?','Reset expedition?','重置探险？'],['Progres peneliti','Researcher progress','研究者进度'],['Lencana misi','Mission badges','任务徽章'],['Tuntas','Complete','已完成'],['Progres tersimpan di browser dan perangkat ini.','Progress is saved in this browser and on this device.','进度已保存在此浏览器和设备中。'],['Mengerti','Got it','知道了'],['Petunjuk','Hint','提示'],['Tutup','Close','关闭'],['Periksa jawaban','Check answer','检查答案'],['Langkah berikutnya','Next step','下一步'],['Selesaikan misi','Complete mission','完成任务'],['Tantangan','Challenge','挑战'],['Di proposal Natasya','In Natasya’s proposal','Natasya 的研究计划'],['Keluaran backbone B0','B0 backbone output','B0 主干网络输出'],['Urutan yang dirakit','Assembled order','组装顺序'],['Pilih blok untuk memasang. Ketuk blok terpasang untuk melepasnya.','Choose a block to install. Click an installed block to remove it.','选择要安装的模块。点击已安装的模块将其移除。'],['Channel attention','Channel attention','通道注意力'],['Spatial attention','Spatial attention','空间注意力'],['Global average pooling','Global average pooling','全局平均池化'],['Klasifikasi','Classifier','分类器'],['Macro-F1 validasi','Validation macro-F1','验证集 Macro-F1'],['Temukan kelas yang tertukar','Find the confused class','找出混淆的类别'],['Confusion matrix','Confusion matrix','混淆矩阵'],['Bandingkan selisih macro-F1','Compare the macro-F1 gap','比较 Macro-F1 差值'],['Periksa sorotan pada latar','Inspect the background highlight','检查背景中的高亮区域'],['Catat jenis kesalahan','Record the error type','记录错误类型'],['Tulis kesimpulan yang didukung','Write a supported conclusion','写出有依据的结论'],['Tepat!','Correct!','正确！'],['Coba lagi','Try again','再试一次'],['Lencana','Badge','徽章'],['XP terkumpul','XP earned','获得的 XP'],['dari','of','/'],['Ilustrasi MRI','MRI illustration','MRI 插图'],['angka simulasi','simulated numbers','模拟数据'],['citra sintetis','synthetic images','合成图像'],['Tanpa tumor','No tumor','无肿瘤'],['Tumor pituitari','Pituitary tumor','垂体瘤'],['Meningioma','Meningioma','脑膜瘤'],['Glioma','Glioma','胶质瘤'],['Internal','Internal','内部测试'],['Eksternal','External','外部测试'],['Perubahan terakhir memindahkan satu citra dari prediksi','The last change moved one image from the prediction','上一次修改将一张图像从预测类别'],['Macro-F1 skenario','Scenario macro-F1','模拟 Macro-F1'],['dataset_audit','dataset_audit','数据审核'],['running seven seeds','running seven seeds','正在运行七个随机种子'],['waiting for run command','waiting for run command','等待运行指令'],['READY','READY','就绪']
];const key='neuroquest-language';let lang=localStorage.getItem(key)||'zh';const sorted=[...T].sort((a,b)=>b[0].length-a[0].length);function tr(source){let out=source;for(const [id,en,zh] of sorted)out=out.split(id).join(lang==='id'?id:lang==='en'?en:zh);return out}function translate(){const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const node of nodes){if(node.parentElement&&['SCRIPT','STYLE'].includes(node.parentElement.tagName))continue;const source=node.__nqSource||(node.__nqSource=node.nodeValue);const next=tr(source);if(node.nodeValue!==next)node.nodeValue=next}document.querySelectorAll('[aria-label],[title],[alt],input[placeholder]').forEach(el=>['aria-label','title','alt','placeholder'].forEach(a=>{if(el.hasAttribute(a)){const source=el.dataset['nq'+a]||(el.dataset['nq'+a]=el.getAttribute(a));el.setAttribute(a,tr(source))}}));document.querySelectorAll('[data-language]').forEach(b=>{b.classList.toggle('active',b.dataset.language===lang);b.setAttribute('aria-pressed',String(b.dataset.language===lang))});document.documentElement.lang=lang==='zh'?'zh-CN':lang==='en'?'en':'id';document.title='NeuroQuest • MRI Brain Lab'}function setLanguage(next){lang=next;localStorage.setItem(key,lang);translate()}document.addEventListener('click',event=>{const button=event.target.closest('[data-language]');if(button)setLanguage(button.dataset.language)});new MutationObserver(translate).observe(document.body,{subtree:true,childList:true,characterData:true});window.setNeuroQuestLanguage=setLanguage;translate()})();
